using ModelContextProtocol.Server;

var builder = WebApplication.CreateBuilder(args);

builder.Services
    .AddMcpServer()
    .WithHttpTransport()
    .WithTools<WeatherTools>()
    .WithResources<ConfigResources>();

var app = builder.Build();

app.MapMcp();

app.Run();

// --- Tools ---

[McpServerToolType]
public static class WeatherTools
{
    [McpServerTool(Name = "get_weather", Title = "Get Weather"),]
    public static string GetWeather(string city)
    {
        // Simulated weather data
        var temps = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase)
        {
            ["Seattle"] = 62,
            ["New York"] = 78,
            ["London"] = 55,
        };

        return temps.TryGetValue(city, out var temp)
            ? $"Weather in {city}: {temp}°F, partly cloudy"
            : $"Weather data not available for '{city}'";
    }
}

// --- Resources ---

[McpServerResourceType]
public static class ConfigResources
{
    /// <summary>Returns application configuration as JSON.</summary>
    [McpServerResource(UriTemplate = "config://app", Name = "app_config", MimeType = "application/json")]
    public static string GetAppConfig()
    {
        var config = new
        {
            appName = "McpHttpServer",
            version = "1.0.0",
            environment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production",
            features = new { caching = true, rateLimit = 100 }
        };
        return System.Text.Json.JsonSerializer.Serialize(config, new System.Text.Json.JsonSerializerOptions { WriteIndented = true });
    }

    /// <summary>Returns supported city list for the weather tool.</summary>
    [McpServerResource(UriTemplate = "config://cities", Name = "supported_cities", MimeType = "application/json")]
    public static string GetSupportedCities()
    {
        return System.Text.Json.JsonSerializer.Serialize(new[] { "Seattle", "New York", "London" });
    }
}

